insert into tax_report_templates
  (country, code, name, periods, valid_from, valid_to, legal_reference, is_periodic_return)
values
  ('LU', 'LU-VAT-PERIODIC', 'Déclaration périodique de TVA (eCDF)', array['month', 'quarter']::declaration_period[], date '2015-01-01', null, 'Loi TVA modifiée du 12 février 1979, art. 64 — formulaire eCDF de déclaration périodique de TVA (TVA_DECM mensuelle, TVA_DECT trimestrielle). Cadence : art. 64, paragraphes 1 à 3 — mensuelle au-dessus de 620 000 euros de chiffre d''affaires, trimestrielle entre 112 000 et 620 000, annuelle en dessous, la déclaration annuelle étant un formulaire distinct que ce pack ne porte pas', true)
on conflict (country, code) do update set
  name               = excluded.name,
  periods            = excluded.periods,
  valid_from         = excluded.valid_from,
  valid_to           = excluded.valid_to,
  legal_reference    = excluded.legal_reference,
  is_periodic_return = excluded.is_periodic_return;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence,
   plus_boxes, minus_boxes, floor_zero, hidden, xml_element, legal_reference, source_key)
values
  ('LU', 'LU-VAT-PERIODIC', '471', 'base', 'a) Ventes à distance intracommunautaires de biens et prestations de services de télécommunication, de radiodiffusion et de télévision ainsi que prestations fournies par voie électronique à des personnes non assujetties dans d''autres États membres et dont la valeur totale annuelle de 10.000 EUR n''est pas dépassée (lieu déterminé par l’article 19quater/1)', '{"de":"a) Innergemeinschaftliche Fernverkäufe von Gegenstäden und Telekommunikations- dienstleistungen, Rundfunk- und Fernsehdienstleistungen, sowie elektronisch erbrachte Dienstleistungen an in anderen Mitgliedsstaaten ansässige Nichtsteuerpflichtige deren jährlicher Gesamtbetrag 10.000 EUR nicht überschreitet (Ort bestimmt von Art.19quater/1)","en":"a) Intra-community distance sales of goods and telecommunications services, radio and television broadcasting services as well as electronically supplied services supplied to non-taxable persons in other Member States for which the total annual value does not exceed EUR 10.000 (place of supply fixed by Art. 19quater/1)"}'::jsonb, 10, '{}'::text[], '{}'::text[], false, false, null, 'Loi TVA modifiée du 12 février 1979, art. 64 — formulaire eCDF de déclaration périodique de TVA (TVA_DECM mensuelle, TVA_DECT trimestrielle), I. Calcul du chiffre d’affaires imposable, « a) Ventes à distance intracommunautaires de biens et prestations de services de télécommunication, de radiodiffusion et de télévision ainsi que prestations fournies par voie électronique à des personnes non assujetties dans d''autres États membres et dont la valeur totale annuelle de 10.000 EUR n''est pas dépassée (lieu déterminé par l’article 19quater/1) » ; Loi TVA, art. 19quater/1 — ventes à distance intracommunautaires sous le seuil de 10 000 EUR', 'loi-tva'),
  ('LU', 'LU-VAT-PERIODIC', '455', 'base', '2. Prélèvements privés de biens et affectation de biens (art.13)', '{"de":"2. Entnahmen von Gegenständen für den privaten Bedarf und Zuordnung von im Unternehmen hergestellten Produkten für Zwecke des Unternehmens (Art.13)","en":"2. Application of goods for non-business use and for business purposes (Art.13)"}'::jsonb, 20, '{}'::text[], '{}'::text[], false, false, null, 'Loi TVA modifiée du 12 février 1979, art. 64 — formulaire eCDF de déclaration périodique de TVA (TVA_DECM mensuelle, TVA_DECT trimestrielle), I. Calcul du chiffre d’affaires imposable, « 2. Prélèvements privés de biens et affectation de biens (art.13) » ; Loi TVA, art. 13', 'loi-tva'),
  ('LU', 'LU-VAT-PERIODIC', '456', 'base', '3. Utilisation privée de biens et prélèvements privés de services (art.16)', '{"de":"3. Benutzung von Betriebsgegenständen und Erbringung von Dienstleistungen für unternehmensfremde Zwecke (Art.16)","en":"3. Non-business use of goods and supply of services free of charge (Art.16)"}'::jsonb, 30, '{}'::text[], '{}'::text[], false, false, null, 'Loi TVA modifiée du 12 février 1979, art. 64 — formulaire eCDF de déclaration périodique de TVA (TVA_DECM mensuelle, TVA_DECT trimestrielle), I. Calcul du chiffre d’affaires imposable, « 3. Utilisation privée de biens et prélèvements privés de services (art.16) » ; Loi TVA, art. 16', 'loi-tva'),
  ('LU', 'LU-VAT-PERIODIC', '457', 'base', '1. Livraisons intracommunautaires de biens à des personnes identifiées à la TVA dans un autre Etat membre (art.43/1/d,e et f) (3)', '{"de":"1. Innergemeinschaftliche Lieferungen an Personen, die eine Id.-Nummer in einem anderen Mitgliedstaat besitzen (Art.43/1/d, e und f) (3)","en":"1. Intra-Community supply of goods to persons identified for VAT purposes in another Member State (MS) (Art.43(1)(d),(e) and (f)) (3)"}'::jsonb, 40, '{}'::text[], '{}'::text[], false, false, null, 'Loi TVA modifiée du 12 février 1979, art. 64 — formulaire eCDF de déclaration périodique de TVA (TVA_DECM mensuelle, TVA_DECT trimestrielle), I. Calcul du chiffre d’affaires imposable, « 1. Livraisons intracommunautaires de biens à des personnes identifiées à la TVA dans un autre Etat membre (art.43/1/d,e et f) (3) » ; Loi TVA, art. 43, par. 1er, points d), e) et f)', 'loi-tva'),
  ('LU', 'LU-VAT-PERIODIC', '014', 'base', '2. Livraisons à l’exportation (art.43/1/a et b)', '{"de":"2. Ausfuhren (Art.43/1/a und b)","en":"2. Exports (Art.43(1)(a) and (b))"}'::jsonb, 50, '{}'::text[], '{}'::text[], false, false, null, 'Loi TVA modifiée du 12 février 1979, art. 64 — formulaire eCDF de déclaration périodique de TVA (TVA_DECM mensuelle, TVA_DECT trimestrielle), I. Calcul du chiffre d’affaires imposable, « 2. Livraisons à l’exportation (art.43/1/a et b) » ; Loi TVA, art. 43, par. 1er, points a) et b)', 'loi-tva'),
