  ('LU', 'intracom_services', 'intra_eu_services', 'Autoliquidation — TVA due par le preneur.', '{"de":"Steuerschuldnerschaft des Leistungsempfängers — die Mehrwertsteuer schuldet der Empfänger.","en":"Reverse charge — VAT is payable by the customer."}'::jsonb, 30, date '1970-01-01', null, 'Loi modifiée du 12 février 1979, art. 63, par. 8, 14° ; art. 17, par. 1er, point b) ; directive 2006/112/CE, art. 44 et 196'),
  ('LU', 'export', 'export', 'Exonération de TVA — exportation hors de l''Union européenne, art. 43, par. 1er, points a) et b), de la loi TVA.', '{"de":"Mehrwertsteuerbefreiung — Ausfuhr außerhalb der Europäischen Union, Art. 43 Abs. 1 Buchst. a) und b) des Mehrwertsteuergesetzes.","en":"Exempt from VAT — export outside the European Union, Art. 43(1)(a) and (b) of the VAT law."}'::jsonb, 40, date '1970-01-01', null, 'Loi modifiée du 12 février 1979, art. 63, par. 8, 13° ; art. 43, par. 1er, points a) et b)'),
  ('LU', 'exempt', 'exempt', 'Exonération de TVA, art. 44 de la loi TVA.', '{"de":"Mehrwertsteuerbefreiung, Art. 44 des Mehrwertsteuergesetzes.","en":"Exempt from VAT, Art. 44 of the VAT law."}'::jsonb, 50, date '1970-01-01', null, 'Loi modifiée du 12 février 1979, art. 63, par. 8, 13° ; art. 44'),
  ('LU', 'cash_basis', 'cash_basis', 'Comptabilité de caisse.', '{"de":"Besteuerung nach vereinnahmten Entgelten.","en":"Cash accounting."}'::jsonb, 60, date '1970-01-01', null, 'Loi modifiée du 12 février 1979, art. 63, par. 8, 8° — mention « Comptabilité de caisse » lorsque la taxe est exigible à l''encaissement du prix ; art. 25'),
  ('LU', 'small_business', 'small_business', 'Régime de franchise pour les petites entreprises, art. 57bis de la loi TVA — TVA non applicable.', '{"de":"Sonderregelung für Kleinunternehmen, Art. 57bis des Mehrwertsteuergesetzes — keine Mehrwertsteuer.","en":"Special scheme for small undertakings, Art. 57bis of the VAT law — VAT not applicable."}'::jsonb, 70, date '1970-01-01', null, 'Loi modifiée du 12 février 1979, art. 57bis, et art. 63, par. 8, 13°'),
  ('LU', 'late_payment', 'late_payment', 'À défaut de paiement à l''échéance, des intérêts de retard sont dus de plein droit, ainsi qu''une indemnité forfaitaire de 40 euros pour les frais de recouvrement.', '{"de":"Wird bei Fälligkeit nicht gezahlt, so sind von Rechts wegen Verzugszinsen sowie eine Pauschale von 40 Euro für Beitreibungskosten geschuldet.","en":"If payment is not made when due, late payment interest is owed as of right, together with a fixed sum of 40 euros for recovery costs."}'::jsonb, 80, date '1970-01-01', null, 'Loi modifiée du 18 avril 2004 relative aux délais de paiement et aux intérêts de retard, art. 3, 4 et 5')
